WF.logs=function(){const STORAGE_KEY="wf_checklist_logs";function _readLogs(){try{const parsed=JSON.parse(localStorage.getItem(STORAGE_KEY));return Array.isArray(parsed)?parsed:[]}catch{return[]}}function _writeLogs(logs){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(logs))}catch(error){console.error("Log write failed:",error)}}return null===localStorage.getItem(STORAGE_KEY)&&_writeLogs([]),{AddLog:function(message){const logs=_readLogs();logs.unshift({Date:Date.now(),Message:message}),_writeLogs(logs.slice(0,1e3))},GetLogs:function(){return _readLogs()}}}();